class TreasureMapEnv:
    GRID_SIZE = 5
    LANDMARK_POOL = ["WELL", "TOWER", "CAVE", "SHRINE", "OAK"]
    NUM_LANDMARKS = 3
    HARD_STEP_LIMIT = 8

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.step_count = 0
        self.terminated = False
        self.truncated = False
        self.milestone_a_awarded = False
        self.milestone_b_awarded = False

        landmark_names = self.rng.sample(self.LANDMARK_POOL, self.NUM_LANDMARKS)
        all_cells = [
            (r, c)
            for r in range(1, self.GRID_SIZE + 1)
            for c in range(1, self.GRID_SIZE + 1)
        ]

        for _ in range(2000):
            pool = list(all_cells)
            self.rng.shuffle(pool)
            chosen = pool[: 1 + self.NUM_LANDMARKS]
            treasure = chosen[0]
            landmarks = dict(zip(landmark_names, chosen[1:]))
            candidates = self._filter_candidates(
                all_cells, landmarks, list(landmark_names), treasure
            )
            if len(candidates) == 1 and candidates[0] == treasure:
                self.treasure = treasure
                self.landmarks = landmarks
                self.landmark_names = landmark_names
                break
        else:
            self.treasure = treasure
            self.landmarks = landmarks
            self.landmark_names = landmark_names

        self.asked = set()

        obs = (
            "You are hunting buried treasure on a {n}x{n} grid. Rows and columns "
            "are numbered 1-{n}. Cells are named R<row>C<col>, e.g. R3C2.\n"
            "Three landmarks are hidden somewhere on the grid: {lm}. None of them "
            "sits on the treasure cell.\n"
            "Goal: find the exact treasure cell within {steps} steps.\n"
            "Actions (send exactly one per turn):\n"
            "  ASK <LANDMARK>   -- e.g. 'ASK {ex}'. Reveals the Chebyshev "
            "('king-move') distance from that landmark to the treasure: "
            "distance = max(|row difference|, |column difference|).\n"
            "  GUESS R<row>C<col> -- e.g. 'GUESS R3C2'. Ends the episode.\n"
            "You may ask each landmark at most once for a fresh clue."
        ).format(
            n=self.GRID_SIZE,
            lm=", ".join(self.landmark_names),
            steps=self.HARD_STEP_LIMIT,
            ex=self.landmark_names[0],
        )
        return obs, {}

    def _chebyshev(self, a, b):
        return max(abs(a[0] - b[0]), abs(a[1] - b[1]))

    def _filter_candidates(self, all_cells, landmarks, revealed_names, treasure):
        landmark_cells = set(landmarks.values())
        candidates = [c for c in all_cells if c not in landmark_cells]
        for name in revealed_names:
            lpos = landmarks[name]
            d = self._chebyshev(treasure, lpos)
            candidates = [c for c in candidates if self._chebyshev(c, lpos) == d]
        return candidates

    def _current_candidates(self):
        all_cells = [
            (r, c)
            for r in range(1, self.GRID_SIZE + 1)
            for c in range(1, self.GRID_SIZE + 1)
        ]
        return self._filter_candidates(
            all_cells, self.landmarks, list(self.asked), self.treasure
        )

    def _parse_cell(self, token):
        token = token.strip().upper()
        if len(token) < 4 or token[0] != "R" or "C" not in token[1:]:
            return None
        try:
            c_index = token.index("C", 1)
            row = int(token[1:c_index])
            col = int(token[c_index + 1 :])
        except ValueError:
            return None
        if not (1 <= row <= self.GRID_SIZE and 1 <= col <= self.GRID_SIZE):
            return None
        return (row, col)

    def step(self, action):
        if self.terminated or self.truncated:
            return "Episode already ended.", 0.0, self.terminated, self.truncated, {}

        self.step_count += 1
        reward = 0.0
        action = (action or "").strip()
        parts = action.split(None, 1)
        verb = parts[0].upper() if parts else ""

        if verb == "ASK" and len(parts) == 2:
            name = parts[1].strip().upper()
            if name not in self.landmark_names:
                obs = (
                    "Unknown landmark '{n}'. Valid landmarks: {lm}."
                ).format(n=name, lm=", ".join(self.landmark_names))
            elif name in self.asked:
                obs = "You already asked {n}; no new information.".format(n=name)
            else:
                self.asked.add(name)
                d = self._chebyshev(self.treasure, self.landmarks[name])
                candidates = self._current_candidates()
                obs = (
                    "{n} reports the treasure is exactly {d} step(s) away "
                    "(king-move distance). {k} cell(s) remain consistent with "
                    "all clues so far."
                ).format(n=name, d=d, k=len(candidates))
                if len(candidates) <= 6 and not self.milestone_a_awarded:
                    reward += 0.15
                    self.milestone_a_awarded = True
                    obs += " (Progress: candidate set narrowed sharply.)"
                if len(candidates) == 1 and not self.milestone_b_awarded:
                    reward += 0.15
                    self.milestone_b_awarded = True
                    obs += " (Progress: location uniquely determined.)"
        elif verb == "GUESS" and len(parts) == 2:
            cell = self._parse_cell(parts[1])
            if cell is None:
                obs = "Malformed guess. Use GUESS R<row>C<col>, e.g. GUESS R3C2."
            elif cell == self.treasure:
                reward = 0.7
                self.terminated = True
                obs = "Correct! The treasure was at {c}.".format(
                    c=self._fmt(cell)
                )
            else:
                self.terminated = True
                obs = "Wrong. The treasure was actually at {c}.".format(
                    c=self._fmt(self.treasure)
                )
        else:
            obs = (
                "Unrecognized action. Use 'ASK <LANDMARK>' or "
                "'GUESS R<row>C<col>'."
            )

        if not self.terminated and self.step_count >= self.HARD_STEP_LIMIT:
            self.truncated = True
            obs += " Step limit reached; episode over."

        return obs, reward, self.terminated, self.truncated, {}

    def _fmt(self, cell):
        return "R{r}C{c}".format(r=cell[0], c=cell[1])

import random


class MirrorRotateSymmetryEnv:
    ALPHABET = "abcdefgh"
    LENGTH = 6
    TRANSFORMS = ["mirror", "rotate_half", "swap_pairs", "alpha_reflect", "reverse_alpha_reflect"]
    MAX_PEEKS = 4
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.secret_name = None
        self.reference = None
        self.target = None
        self.witness = None
        self.target_answer = None
        self.peeked = {}
        self.consistent = set()
        self.best_consistent_size = None
        self.steps = 0
        self.done = False

    def _apply(self, name, s):
        n = len(s)
        lo = ord(self.ALPHABET[0])
        hi = ord(self.ALPHABET[-1])
        if name == "mirror":
            return s[::-1]
        if name == "rotate_half":
            h = n // 2
            return s[h:] + s[:h]
        if name == "swap_pairs":
            chars = list(s)
            for i in range(0, n - 1, 2):
                chars[i], chars[i + 1] = chars[i + 1], chars[i]
            return "".join(chars)
        if name == "alpha_reflect":
            return "".join(chr(lo + hi - ord(c)) for c in s)
        if name == "reverse_alpha_reflect":
            reflected = "".join(chr(lo + hi - ord(c)) for c in s)
            return reflected[::-1]
        raise ValueError(name)

    def _rand_string(self, distinct):
        if distinct:
            letters = list(self.ALPHABET)
            self.rng.shuffle(letters)
            return "".join(letters[: self.LENGTH])
        return "".join(self.rng.choice(self.ALPHABET) for _ in range(self.LENGTH))

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.secret_name = self.rng.choice(self.TRANSFORMS)
        self.reference = self._rand_string(distinct=True)
        while True:
            self.target = self._rand_string(distinct=False)
            if self.target != self.reference:
                break
        self.witness = self._apply(self.secret_name, self.reference)
        self.target_answer = self._apply(self.secret_name, self.target)
        self.peeked = {}
        self.consistent = set(self.TRANSFORMS)
        self.best_consistent_size = len(self.consistent)
        self.steps = 0
        self.done = False

        obs = (
            "SYMMETRY LAB. A hidden transformation T (one of 5 fixed symmetry "
            "operations on 6-letter strings over alphabet a-h) was applied to "
            f"reference string R = '{self.reference}' to produce a hidden witness "
            "string W = T(R). You cannot see W directly.\n"
            f"Goal: determine T well enough to predict T(TARGET) for the held-out "
            f"string TARGET = '{self.target}'.\n"
            "Actions (exactly one per turn):\n"
            f"  PEEK:<index>    reveal W[index] for index in 0..{self.LENGTH-1} "
            f"(each index usable once, at most {self.MAX_PEEKS} peeks total).\n"
            "  ANSWER:<string> submit your predicted 6-letter T(TARGET); ends the episode.\n"
            f"You have {self.MAX_STEPS} turns total."
        )
        info = {"reference": self.reference, "target": self.target}
        return obs, info

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        action = (action or "").strip()
        reward = 0.0
        terminated = False
        truncated = False
        info = {}

        if action.upper().startswith("PEEK:"):
            if len(self.peeked) >= self.MAX_PEEKS:
                obs = f"Peek budget ({self.MAX_PEEKS}) exhausted. Submit ANSWER:<string> instead."
            else:
                idx_str = action[5:].strip()
                if not idx_str.lstrip("-").isdigit():
                    obs = f"Malformed PEEK: '{idx_str}' is not an integer. Use PEEK:<0-{self.LENGTH-1}>."
                else:
                    idx = int(idx_str)
                    if idx < 0 or idx >= self.LENGTH:
                        obs = f"Index {idx} out of range 0..{self.LENGTH-1}."
                    elif idx in self.peeked:
                        obs = f"Index {idx} already peeked: W[{idx}] = '{self.peeked[idx]}'. Choose a new index."
                    else:
                        revealed = self.witness[idx]
                        self.peeked[idx] = revealed
                        self.consistent = {
                            name for name in self.consistent
                            if self._apply(name, self.reference)[idx] == revealed
                        }
                        obs = (
                            f"W[{idx}] = '{revealed}'. Consistent-hypothesis count: "
                            f"{len(self.consistent)} of {len(self.TRANSFORMS)}."
                        )
                        if len(self.consistent) < self.best_consistent_size:
                            reward += 0.1
                            self.best_consistent_size = len(self.consistent)
        elif action.upper().startswith("ANSWER:"):
            guess = action[7:].strip().lower()
            terminated = True
            self.done = True
            if guess == self.target_answer:
                reward += 0.6
                obs = f"Correct. T(TARGET) = '{self.target_answer}'. Episode solved."
            else:
                obs = (
                    f"Incorrect. You answered '{guess}', the true value was "
                    f"'{self.target_answer}'. Episode over."
                )
        else:
            obs = "Malformed action. Use 'PEEK:<index>' or 'ANSWER:<string>'."

        if not terminated and self.steps >= self.MAX_STEPS:
            truncated = True
            self.done = True
            obs += " Step limit reached; episode truncated."

        return obs, reward, terminated, truncated, info

